from pathlib import Path
import re, numpy as np
from pynwb import NWBHDF5IO
zones={'A':(80,130),'B':(200,250),'C':(320,370)}
inside=0; total=0; outside=[]; env_switch=[]; zone_sessions=[]
for p in sorted(Path('/app/data').glob('sub-*/*.nwb')):
 with NWBHDF5IO(str(p),'r',load_namespaces=True) as io:
  n=io.read(); scene=n.identifier.rstrip('/').split('/')[-1]; b=n.processing['behavior']['BehavioralTimeSeries'].time_series
  m=re.search(r'Location([ABC])(?:_to_([ABC]))?$',scene)
  if m: z0,z1=m.group(1),m.group(2)
  else:
   m=re.search(r'Env\d_([ABC])_to_Env\d_([ABC])$',scene); z0,z1=m.group(1),m.group(2)
  st=np.flatnonzero(np.asarray(b['trial_start'].data[:])); tp=np.flatnonzero(np.asarray(b['teleport'].data[:])); pos=np.asarray(b['position'].data[:]); t=np.asarray(b['position'].timestamps[:]); env=np.asarray(b['environment'].data[:])
  rts=np.asarray(b['Reward'].timestamps[:]); ridx=np.searchsorted(t,rts); ridx=np.clip(ridx,0,len(t)-1)
  for j,(a,z) in enumerate(zip(st,tp)):
   lab=z0 if z1 is None or j<30 else z1
   for ii in ridx[(ridx>=a)&(ridx<z)]:
    total+=1
    if zones[lab][0]-1<=pos[ii]<=zones[lab][1]+1: inside+=1
    else: outside.append((str(p.relative_to('/app/data')),scene,j,lab,float(pos[ii]),float(t[ii])))
  if z1:
   zone_sessions.append((scene,len(st)))
   tr_env=[int(round(np.median(env[a:z]))) for a,z in zip(st,tp)]
   changes=np.flatnonzero(np.diff(tr_env)!=0)+1
   if 'to_Env' in scene: env_switch.append((str(p.relative_to('/app/data')),scene,changes.tolist(),tr_env[29:32]))
print('reward events in assigned zone ±1cm',inside,'/',total,'=',inside/total)
print('outside count',len(outside),'first20'); [print(x) for x in outside[:20]]
print('switch session trial count min/max',min(n for _,n in zone_sessions),max(n for _,n in zone_sessions),'n',len(zone_sessions))
print('cross environment switches'); [print(x) for x in env_switch]
